import{_ as t,o,c as d,a0 as s}from"./chunks/framework.l1I-fhud.js";const p=JSON.parse('{"title":"tamias serve — JSON-RPC over stdio","description":"","frontmatter":{},"headers":[],"relativePath":"reference/serve.md","filePath":"reference/serve.md"}'),a={name:"reference/serve.md"};function r(i,e,c,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="tamias-serve-—-json-rpc-over-stdio" tabindex="-1"><code>tamias serve</code> — JSON-RPC over stdio <a class="header-anchor" href="#tamias-serve-—-json-rpc-over-stdio" aria-label="Permalink to &quot;\`tamias serve\` — JSON-RPC over stdio&quot;">​</a></h1><p><code>tamias serve</code> runs tamias as an <strong>ndjson JSON-RPC service</strong>: one JSON request per line on stdin, one JSON response per line on stdout. It&#39;s the embedding surface — a parent process (an agent harness, a daemon) drives installs without shelling out per verb.</p><h2 id="framing" tabindex="-1">Framing <a class="header-anchor" href="#framing" aria-label="Permalink to &quot;Framing&quot;">​</a></h2><p>Request: <code>{&quot;op&quot;: &quot;&lt;op&gt;&quot;, …fields}</code> Response: <code>{&quot;ok&quot;: true, &quot;result&quot;: …}</code> or <code>{&quot;ok&quot;: false, &quot;error&quot;: &quot;…&quot;}</code></p><p>A failed op returns <code>ok:false</code> — it does not kill the service. The service exits when stdin closes.</p><h2 id="ops" tabindex="-1">Ops <a class="header-anchor" href="#ops" aria-label="Permalink to &quot;Ops&quot;">​</a></h2><table tabindex="0"><thead><tr><th>op</th><th>fields</th><th>result</th></tr></thead><tbody><tr><td><code>install</code></td><td><code>ref</code>, <code>allow_drivers?</code></td><td><code>{label, resolved, digest}</code></td></tr><tr><td><code>sync</code></td><td><code>locked?</code>, <code>allow_drivers?</code>, <code>dir?</code></td><td><code>{deps: [{dep, status, detail}], failed}</code> — reconciles the project manifest&#39;s <code>deps:</code> against the store + <code>tamias.lock</code> (<code>dir</code> defaults to the server&#39;s cwd)</td></tr><tr><td><code>list</code></td><td>—</td><td><code>[{label, source_ref, digest}]</code></td></tr><tr><td><code>info</code></td><td><code>name</code></td><td><code>{label, resolved, digest, size}</code></td></tr><tr><td><code>verify</code></td><td><code>name</code></td><td><code>{name, ok, signature, trust, signer}</code> — <code>trust</code>/<code>signer</code> are re-derived live, same rule as <code>tamias verify</code></td></tr><tr><td><code>remove</code></td><td><code>name</code></td><td><code>{name}</code> — runs driver teardown first, like <code>tamias uninstall</code></td></tr><tr><td><code>search</code></td><td><code>query</code>, <code>registry?</code></td><td><code>{results: [{label, name, scope, version, kind, digest, file}]}</code></td></tr><tr><td><code>publish</code></td><td><code>dir</code>, <code>registry?</code></td><td><code>{label, name, scope, version, kind, digest, file}</code></td></tr><tr><td><code>registry.list</code></td><td>—</td><td><code>{registries: [{name, kind, effective_kind, url, token_env, limits}]}</code></td></tr><tr><td><code>registry.get</code></td><td><code>name</code></td><td>one registry object (same shape as <code>registry.list</code> items)</td></tr><tr><td><code>registry.add</code></td><td><code>name</code>, <code>kind</code>, <code>url</code>, <code>token_env?</code></td><td><code>{name, config}</code> — writes the config file</td></tr><tr><td><code>registry.remove</code></td><td><code>name</code></td><td><code>{name, config}</code></td></tr></tbody></table><p><code>name</code> accepts <code>@scope/name</code> or bare <code>name</code>, same as the CLI.</p><p><code>search</code>/<code>publish</code> take <code>registry</code> as a <strong>name or raw ref</strong> — identical resolution to <code>--registry</code> on the CLI verbs: config <code>registries</code> name → raw dir/http ref → routing defaults (<code>search.default</code> → <code>publish.default</code>) → <code>TAMIAS_REGISTRY</code> env → the local default root. <code>registry.add</code>/<code>remove</code> write <code>tamias.{yml,yaml,toml}</code> through the same path as <code>tamias registry add|remove</code>; <code>token_env</code> is an env var <em>name</em>, never a token value.</p><h2 id="driver-consent" tabindex="-1">Driver consent <a class="header-anchor" href="#driver-consent" aria-label="Permalink to &quot;Driver consent&quot;">​</a></h2><p><code>install</code> refuses payload-shipped <code>drivers/</code> unless the request carries <code>&quot;allow_drivers&quot;: true</code> (or <code>TAMIAS_ALLOW_DRIVERS=1</code> is set) — identical to <code>--allow-drivers</code>. Bundled drivers are never registered or executed without it; once consented, the grant is remembered per package + payload digest in <code>consented.json</code> (see <a href="/tamias/explanation/security.html">Security model</a>).</p><h2 id="trust-boundary" tabindex="-1">Trust boundary <a class="header-anchor" href="#trust-boundary" aria-label="Permalink to &quot;Trust boundary&quot;">​</a></h2><p><strong>Stdin is fully trusted.</strong> Any process that can write to the service&#39;s stdin can pass <code>&quot;allow_drivers&quot;: true</code> and reach every op — there is no per-request authentication. Embed <code>tamias serve</code> only behind a harness that has already made the trust decision; never expose it to untrusted input.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><p>The service honors the same roots as the CLI: <code>TAMIAS_HOME</code> (store + <code>drivers/</code>), <code>TAMIAS_CACHE</code>, <code>TAMIAS_REGISTRY</code>, <code>TAMIAS_CONFIG</code> (the config file <code>registry.*</code> ops read/write and <code>search</code>/<code>publish</code> resolve against — re-read per request, so writes are visible in-session), and the telemetry vars (<code>TAMIAS_OTEL_*</code>).</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s\\n&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;{&quot;op&quot;:&quot;install&quot;,&quot;ref&quot;:&quot;./hello&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;{&quot;op&quot;:&quot;list&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;{&quot;op&quot;:&quot;verify&quot;,&quot;name&quot;:&quot;hello&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/tamias/reference/scripting.html">Scripting tamias</a> — <code>--json</code>, <code>manifest</code>, <code>schema</code></li><li><a href="/tamias/explanation/security.html">Security model</a></li></ul>`,19)])])}const m=t(a,[["render",r]]);export{p as __pageData,m as default};
